"Mit Google ist nichts einzutragen: TW-CAD nimmt automatisch den Schlüssel aus der Master-App (gleicher Browser). Abgerechnet wird über dein Google-Konto.": "S Googlom netreba nič zadávať: TW-CAD automaticky použije kľúč z Master aplikácie (rovnaký prehliadač). Účtuje sa cez váš účet Google.",
"z. B.: Bad 2,80 × 2,20 m Innenmaß, Wände 11,5 cm, Tür 88,5 unten links mit 15 cm Abstand, Fenster 101 rechts mittig BRH 1,50, Boden 60×30 Drittelverband, Wand 30×60 bis 2,10 m": "napr.: Kúpeľňa 2,80 × 2,20 m vnútorný rozmer, steny 11,5 cm, dvere 88,5 dole vľavo 15 cm od rohu, okno 101 vpravo v strede, parapet 1,50, podlaha 60×30 väzba na tretinu, stena 30×60 do 2,10 m",
"Zeichnen per Text": "Kreslenie textom",
"Plan ändern per Sprache oder Text": "Zmena plánu hlasom alebo textom",
"Sag einfach, was geändert werden soll: „Fenster im Bad 1,01 breiter“, „Wand zwischen Küche und Flur 2 cm dicker“, „WC im Gäste-WC an die Nordwand“, „Boden im Flur 60 × 60 Kreuzfuge“ oder frag „wie groß ist das Bad?“. Mit Mikrofon-Knopf auch gesprochen. Kurzbefehl überall: Strg+K.": "Jednoducho povedzte, čo sa má zmeniť: „okno v kúpeľni o 1,01 širšie“, „stena medzi kuchyňou a chodbou o 2 cm hrubšia“, „WC na toalete pre hostí k severnej stene“, „podlaha v chodbe 60 × 60 priebežná škára“ alebo sa opýtajte „aká veľká je kúpeľňa?“. Tlačidlom mikrofónu aj hlasom. Skratka všade: Ctrl+K.",
"Grundriss aus Raumprogramm entwerfen": "Navrhnúť pôdorys z programu miestností",
"Raumprogramm beschreiben (Räume, Größen, Geschosse, Grundstück) – die KI entwirft einen DIN-gerechten Grundriss und TW-CAD baut ihn als neues Projekt mit Wänden, Räumen, Türen, Fenstern, Treppe und Dach auf.": "Opíšte program miestností (miestnosti, veľkosti, podlažia, pozemok) – AI navrhne pôdorys podľa noriem DIN a TW-CAD z neho vytvorí nový projekt so stenami, miestnosťami, dverami, oknami, schodiskom a strechou.",
"Visualisierung": "Vizualizácia",
"In „3D & Fassade“ (oder „Raum von innen“) rechts unter Export: „KI-Visualisierung“ – die KI schreibt aus dem 3D-Bild fertige Prompts für Bild-KIs (ChatGPT, Firefly, Midjourney) plus Referenzbild und Kundentext.": "V „3D a fasáda“ (alebo „Miestnosť zvnútra“) vpravo pod Export: „AI vizualizácia“ – AI z 3D obrázka napíše hotové prompty pre obrazové AI (ChatGPT, Firefly, Midjourney) a k tomu referenčný obrázok a text pre zákazníka.",
"Leistungsverzeichnis auswerten": "Vyhodnotiť výkaz výmer",
"LV als PDF, GAEB (X83/D83) oder Text: die KI findet alle Fliesenpositionen mit Hersteller, Serie, Format, Farbe und Fuge und legt sie in der Fliesen-Bibliothek dieses Projekts an. Danach im Fliesenplan „Aus LV/Bibliothek“.": "Výkaz výmer ako PDF, GAEB (X83/D83) alebo text: AI nájde všetky položky obkladov a dlažieb s výrobcom, sériou, formátom, farbou a škárou a uloží ich do knižnice dlaždíc tohto projektu. Potom v pláne obkladov „Z výkazu/knižnice“.",
