"Treppe passt nicht in „{0}“ ({1} × {2} m) – bitte mit dem Treppen-Werkzeug einsetzen (z. B. gewendelt).": "Schodisko sa nezmestí do „{0}“ ({1} × {2} m) – vložte ho nástrojom Schodisko (napr. točité).",
"z. B.: Einfamilienhaus für 4 Personen, ca. 140 m² Wohnfläche, 2 Geschosse mit Satteldach 38°.\nEG: Diele mit Garderobe, Gäste-WC, Küche offen zu Essen/Wohnen ca. 40 m² nach Süden, Hauswirtschaftsraum, Arbeitszimmer 10 m².\nOG: Eltern 15 m² mit Ankleide, 2 Kinderzimmer je 12 m², Bad 10 m² mit bodengleicher Dusche und Wanne, Abstellraum.\nGrundstück: Haus max. 11 × 9 m, Zufahrt von Westen.": "napr.: rodinný dom pre 4 osoby, cca 140 m² obytnej plochy, 2 podlažia so sedlovou strechou 38°.\nPrízemie: predsieň so šatníkom, WC pre hostí, kuchyňa otvorená do jedálne/obývačky cca 40 m² na juh, technická miestnosť, pracovňa 10 m².\nPoschodie: rodičia 15 m² so šatníkom, 2 detské izby po 12 m², kúpeľňa 10 m² s bezbariérovým sprchovým kútom a vaňou, komora.\nPozemok: dom max. 11 × 9 m, príjazd zo západu.",
"Die KI entwirft einen Grundriss als Vorschlag (Achsmaße, Raster 12,5 cm) und TW-CAD baut ihn als neues Projekt mit Wänden, Räumen, Türen, Fenstern, Treppe und Dach auf. Danach normal weiterbearbeiten – nichts im aktuellen Projekt wird überschrieben.": "AI navrhne pôdorys (osové rozmery, raster 12,5 cm) a TW-CAD z neho vytvorí nový projekt so stenami, miestnosťami, dverami, oknami, schodiskom a strechou. Potom bežne pokračujte – nič v aktuálnom projekte sa neprepíše.",
"Die KI entwirft … (ca. 20–60 Sekunden)": "AI navrhuje … (cca 20–60 sekúnd)",
"Kein Grundriss in der Antwort": "V odpovedi nie je pôdorys",
