"Summe": "Spolu",
"Netto-Raumfläche nach Nutzungsgruppen": "Čistá podlahová plocha podľa skupín využitia",
"Nutzungsgruppe": "Skupina využitia",
"NRF gesamt (inkl. Außenflächen)": "NRF spolu (vr. vonkajších plôch)",
"Raumliste": "Zoznam miestností",
"Flächen sind Netto-Raumflächen aus dem Modell (Innenmaß der Wände, ohne Putzabzug). Wohnfläche nach Wohnflächenverordnung (WoFlV): Raumteile ab 2 m lichter Höhe voll, 1–2 m zur Hälfte, unter 1 m nicht; Balkone/Terrassen in der Regel zu einem Viertel; Keller, Heizungsräume und Garagen zählen nicht zur Wohnfläche. BGF = Brutto-Grundfläche (Außenmaß), KGF = BGF − NRF, BRI ≈ BGF × Geschosshöhe.": "Plochy sú čisté plochy miestností z modelu (vnútorný rozmer stien, bez odpočtu omietky). Obytná plocha podľa nemeckej vyhlášky WoFlV: časti miestností so svetlou výškou od 2 m plne, 1–2 m polovicou, pod 1 m vôbec; balkóny/terasy spravidla štvrtinou; pivnice, kotolne a garáže sa do obytnej plochy nezapočítavajú. BGF = hrubá podlahová plocha (vonkajší rozmer), KGF = konštrukčná plocha = BGF − NRF (čistá plocha), BRI ≈ BGF × konštrukčná výška podlažia (obostavaný priestor).",
