"Nutzung wird aus dem Raumnamen vorgeschlagen (Bad → NUF 7, Flur → VF, Heizung → TF …) und lässt sich je Raum ändern. Dachschrägen werden aus dem Dach berechnet: Wohnfläche ≥ 2 m voll, 1–2 m halb, unter 1 m nicht (§ 4 WoFlV).": "Využitie sa navrhuje podľa názvu miestnosti (Kúpeľňa → NUF 7, Chodba → VF, Kotolňa → TF …) a dá sa zmeniť pre každú miestnosť. Šikmé stropy sa počítajú zo strechy: obytná plocha ≥ 2 m plne, 1–2 m polovicou, pod 1 m nie (§ 4 WoFlV).",
