"Regelwerk: {0} · Barrierefreiheit: {1} · {2} Fehler, {3} Hinweise, {4} erfüllt. Vereinfachte Prüfung aus dem CAD-Modell – ersetzt keine bauaufsichtliche Prüfung.": "Predpisy: {0} · bezbariérovosť: {1} · {2} chýb, {3} upozornení, {4} splnených. Zjednodušená kontrola z modelu CAD – nenahrádza úradnú kontrolu stavebného úradu.",
"KI-Erläuterung": "Vysvetlenie AI",
"Raumhöhen, Belichtung, Türen, Treppen (DIN 18065), Absturzsicherung, Bewegungsflächen (DIN 18040-2) – Zeile anklicken = im Plan zeigen": "Výšky miestností, osvetlenie, dvere, schodiská (DIN 18065), zábradlia, manipulačné plochy (DIN 18040-2) – kliknutím na riadok = zobraziť v pláne",
"Bauordnung ": "Stavebný poriadok ",
"Barrierefreiheit ": "Bezbariérovosť ",
"🤖 KI-Erläuterung": "🤖 Vysvetlenie AI",
"schließen": "zavrieť",
"Keine Einträge in dieser Auswahl.": "V tomto výbere nie sú žiadne položky.",
"Noch nichts zu prüfen – zeichne Wände, Räume, Türen und Fenster.": "Zatiaľ nie je čo kontrolovať – nakreslite steny, miestnosti, dvere a okná.",
"Vereinfachte Prüfung aus dem Modell nach {0}, DIN 18065 und DIN 18040-2. Sie ersetzt keine bauaufsichtliche Prüfung; im Zweifel gilt der Normtext bzw. die Landesbauordnung. Räume ohne Aufenthalt (Bad, Flur, Abstellraum …) werden bei Raumhöhe und Belichtung nicht geprüft – die Nutzung stellst du im Raumbuch ein.": "Zjednodušená kontrola z modelu podľa {0}, DIN 18065 (schodiská) a DIN 18040-2 (bezbariérové byty). Nenahrádza úradnú kontrolu; v prípade pochybností platí text normy, resp. krajinský stavebný poriadok. Miestnosti bez pobytu (kúpeľňa, chodba, komora …) sa z hľadiska výšky a osvetlenia nekontrolujú – využitie nastavíte v tabuľke miestností.",
"Erst KI einrichten (Stern-Knopf oben) – dann erklärt sie die Prüfung.": "Najprv nastavte AI (tlačidlo s hviezdou hore) – potom kontrolu vysvetlí.",
"Alles erfüllt – die Prüfung hat keine Fehler oder Hinweise gefunden. 👍": "Všetko splnené – kontrola nenašla chyby ani upozornenia. 👍",
